ALTER TABLE public.transactions ADD COLUMN package_id uuid REFERENCES public.packages(id), ADD COLUMN started_at timestamptz, ADD COLUMN ends_at timestamptz;
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.transactions(id), amount numeric(12,2) NOT NULL CHECK (amount > 0), method text NOT NULL CHECK (method IN ('Cash','QRIS','Transfer')), kind text NOT NULL CHECK (kind IN ('dp','payment')), created_at timestamptz NOT NULL DEFAULT now(), recorded_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT ON public.payments TO authenticated;
GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_staff_read ON public.payments FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'owner') OR public.is_receptionist(auth.uid()));
CREATE OR REPLACE FUNCTION public.create_reservation(_mode text, _room_id uuid, _package_id uuid, _name text, _phone text, _address text, _amount numeric, _method text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE selected_price numeric(12,2); duration integer; selected_guest uuid; selected_transaction uuid; number text; BEGIN IF NOT (public.has_role(auth.uid(), 'owner') OR public.is_receptionist(auth.uid())) THEN RAISE EXCEPTION 'Akses ditolak'; END IF; IF _mode NOT IN ('booking','check_in') OR _mode IS NULL OR _method NOT IN ('Cash','QRIS','Transfer') OR _method IS NULL THEN RAISE EXCEPTION 'Jenis transaksi atau metode pembayaran tidak valid'; END IF; IF length(trim(coalesce(_name,''))) NOT BETWEEN 1 AND 100 OR coalesce(_phone,'') !~ '^[0-9+]{8,16}$' OR length(coalesce(_address,'')) > 500 THEN RAISE EXCEPTION 'Data tamu tidak valid'; END IF; SELECT price, duration_minutes INTO selected_price, duration FROM public.packages WHERE id = _package_id AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Paket tidak tersedia'; END IF; IF _amount IS NULL OR _amount < 0 OR _amount > selected_price THEN RAISE EXCEPTION 'Nominal pembayaran tidak valid'; END IF; IF _mode = 'check_in' THEN UPDATE public.rooms SET status='occupied' WHERE id=_room_id AND status='ready' AND active AND NOT EXISTS (SELECT 1 FROM public.transactions WHERE room_id=_room_id AND status='booking'); IF NOT FOUND THEN RAISE EXCEPTION 'Kamar tidak tersedia atau telah dipesan'; END IF; ELSE PERFORM 1 FROM public.rooms WHERE id=_room_id AND status='ready' AND active FOR UPDATE; IF NOT FOUND OR EXISTS (SELECT 1 FROM public.transactions WHERE room_id=_room_id AND status='booking') THEN RAISE EXCEPTION 'Kamar tidak tersedia atau telah dipesan'; END IF; END IF; SELECT id INTO selected_guest FROM public.guests WHERE phone=_phone; IF selected_guest IS NULL THEN IF length(trim(coalesce(_address,'')))=0 THEN RAISE EXCEPTION 'Alamat wajib diisi untuk tamu baru'; END IF; INSERT INTO public.guests(full_name,address,phone) VALUES(trim(_name),trim(_address),_phone) RETURNING id INTO selected_guest; END IF; INSERT INTO public.transactions(guest_id,room_id,package_id,status,created_by,price_snapshot,started_at,ends_at) VALUES(selected_guest,_room_id,_package_id,_mode::public.transaction_status,auth.uid(),selected_price,CASE WHEN _mode='check_in' THEN now() END,CASE WHEN _mode='check_in' THEN now() + duration * interval '1 minute' END) RETURNING id,transaction_number INTO selected_transaction,number; IF _amount > 0 THEN INSERT INTO public.payments(transaction_id,amount,method,kind,recorded_by) VALUES(selected_transaction,_amount,_method,CASE WHEN _mode='booking' THEN 'dp' ELSE 'payment' END,auth.uid()); END IF; RETURN number; END $$;
REVOKE ALL ON FUNCTION public.create_reservation(text,uuid,uuid,text,text,text,numeric,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_reservation(text,uuid,uuid,text,text,text,numeric,text) TO authenticated;